(491,'_site_transient_feed_0d2db5fea5a8633b56992c916819b198','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:52:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\n \n	\n		\n		\n		\n		\n		\n		\n		\n		\n		\n	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:8:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"Blog – WordPress.org Français\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://fr.wordpress.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:13:\"lastBuildDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 10 Jan 2026 23:18:11 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"fr-FR\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"generator\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://wordpress.org/?v=7.1-alpha-62353\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"image\";a:1:{i:0;a:6:{s:4:\"data\";s:11:\"\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:3:\"url\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://s.w.org/favicon.ico?2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"Blog – WordPress.org Français\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:24:\"https://fr.wordpress.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"width\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"height\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"Arrêt du support des versions 7.2 et 7.3 de PHP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://fr.wordpress.org/2026/01/10/arret-support-php-version-72-73/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 10 Jan 2026 08:29:22 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Securité\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://fr.wordpress.org/?p=3423\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:383:\"À partir de WordPress 7.0 (version attendue en avril 2026), les versions 7.2 et 7.3 de PHP ne seront plus supportées par notre CMS. La&#160;version minimale recommandée&#160;de PHP restera 8.3, tandis que la&#160;version minimale supportée&#160;de PHP sera dorénavant la version 7.4. La version minimale supportée de PHP avait été montée à 7.2.24 en juillet 2024. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Jb Audras\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:4900:\"\n<p class=\"wp-block-paragraph\">À partir de WordPress 7.0 (version attendue en avril 2026), les versions 7.2 et 7.3 de PHP ne seront plus supportées par notre CMS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La&nbsp;<em>version minimale recommandée</em>&nbsp;de PHP restera 8.3, tandis que la&nbsp;<em>version minimale supportée</em>&nbsp;de PHP sera dorénavant la version 7.4.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La version minimale supportée de PHP avait été montée à 7.2.24 en juillet 2024. Depuis, les parts de marché combinées de PHP 7.2 et 7.3 dans l&rsquo;écosystème WordPress sont tombés <a href=\"https://fr.wordpress.org/about/stats/\">sous le seuil de 4 % des installations WordPress</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Historiquement, le projet WordPress définit à 5 % le seuil d&rsquo;utilisation minimal pour qu&rsquo;une version de PHP puisse être retirée du support. L&rsquo;utilisation combinée de PHP 7.2 et 7.3 étant désormais bien inférieure à 5 % d&rsquo;installations, le processus d&rsquo;augmentation de la version minimale de PHP requise peut être lancé.</p>\n\n\n\n<p class=\"wp-block-paragraph\">L&rsquo;objectif de l&rsquo;augmentation de la version minimale de PHP requise est de garantir la maintenabilité à long terme de WordPress. Les avantages de cette augmentation se manifestent progressivement dans de nombreux domaines&nbsp;: l&rsquo;écosystème des extensions et des thèmes, les outils et bibliothèques, la perception à long terme du projet WordPress, les relations avec les développeur·euses et, à terme, le code source de WordPress lui-même, notamment ses outils de développement et son infrastructure de tests automatisés.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Quelles projections à moyen terme sur le support de PHP par WordPress&nbsp;?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Il n&rsquo;est pas prévu d&rsquo;augmenter la version minimale de PHP requise selon un calendrier fixe. Les équipes <em><bdo lang=\"en\" dir=\"ltr\">Core</bdo></em> et <bdo lang=\"en\" dir=\"ltr\"><em>Security</em></bdo> de WP continueront de surveiller l&rsquo;utilisation des versions de PHP et de collaborer avec l&rsquo;équipe <em><bdo lang=\"en\" dir=\"ltr\">Hosting</bdo></em> (constituée d&rsquo;hébergeurs qui contribuent activement à WordPress) afin d&rsquo;inciter l&rsquo;écosystème à mettre à jour leur version de PHP le plus rapidement possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Le seuil d&rsquo;utilisation de 5&nbsp;% restera la norme pour le moment pour décider de l&rsquo;arrêt ou non du support d&rsquo;une version.</p>\n\n\n\n<h3 class=\"wp-block-heading\">PHP 7.4, le principal goulot d&rsquo;étranglement pour monter la version minimale supportée de PHP </h3>\n\n\n\n<p class=\"wp-block-paragraph\">À ce jour, PHP 7.4 est le principal goulot d&rsquo;étranglement empêchant d&rsquo;aller plus loin. Voici en effet les parts de marché de chaque version de PHP dans l&rsquo;écosystème WP, au 10 janvier 2026&nbsp;:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>8.5 : 0,23&nbsp;%</li>\n\n\n\n<li>8.4 : 4,90&nbsp;%</li>\n\n\n\n<li>8.3 : 16,74&nbsp;%</li>\n\n\n\n<li>8.2 : 27,29&nbsp;%</li>\n\n\n\n<li>8.1 : 15,39&nbsp;%</li>\n\n\n\n<li>8.0 : 5,69&nbsp;%</li>\n\n\n\n<li><strong>7.4 : 22,20&nbsp;%</strong></li>\n\n\n\n<li>7.3 : 2,04&nbsp;% (arrêt du support en avril 2026)</li>\n\n\n\n<li>7.2 : 1,81&nbsp;% (arrêt du support en avril 2026)</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Avec 22,2% de parts de marché, PHP 7.4 risque de ne pas pouvoir être abandonné avant plusieurs années. Or, cette version est sortie en 2019 et son support officiel par PHP s&rsquo;est arrêté en 2022.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Malheureusement, en dehors même de WordPress, il existe une multitude d&rsquo;applications et de sites construits sur d&rsquo;anciennes versions de PHP et qui sont incompatibles avec les versions ultérieures. C&rsquo;est sans doute pour cela que tant d&rsquo;hébergeurs proposent toujours PHP 7.4 à leurs clients, et qu&rsquo;il leur est si difficile d&rsquo;opérer des mises à niveau forcées vers des versions plus récentes&nbsp;: tant qu&rsquo;aucune faille de sécurité majeure ne sera publiée concernant PHP 7.4, il y a de fortes chances que ce <em>statu quo</em> demeure chez les hébergeurs importants, qui peuvent difficilement imposer une telle migration sur leur parc et risquer de casser des applicatifs critiques pour leurs clients.</p>\n\n\n\n<p class=\"wp-block-paragraph\">En attendant, <strong>WordPress est entièrement compatible avec PHP 8.3 qui est la version minimale officiellement recommandée pour faire tourner WP</strong>. Et <a href=\"https://make.wordpress.org/core/handbook/references/php-compatibility-and-wordpress-versions/\">la compatibilité 8.4 et 8.5 est presque complète (en anglais)</a> au niveau du cœur du CMS. N&rsquo;attendez pas pour effectuer la montée de version de PHP de votre côté&nbsp;!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3423\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:26:\"WordPress 6.9 « Gene »\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://fr.wordpress.org/2025/12/02/wordpress-6-9-gene/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 02 Dec 2025 20:17:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Nouvelles versions de WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://fr.wordpress.org/?p=3411\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:350:\"Chaque version de WordPress rend hommage à un artiste ayant laissé une marque indélébile dans le monde la musique. Le nom de code de WordPress 6.9 est «&#160;Gene&#160;», en l&#8217;honneur du jazzman américain Gene Harris. Ce pianiste autodidacte dès l&#8217;âge de 6 ans a infusé le jazz populaire de soul de blues et de gospel, [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Jb Audras\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:78347:\"\n<figure class=\"wp-block-image size-full\"><img fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"535\" src=\"https://fr.wordpress.org/files/2025/12/Release-Edition-Featured-Image-6.9-1024x535-1.png\" alt=\"\" class=\"wp-image-3413\" srcset=\"https://fr.wordpress.org/files/2025/12/Release-Edition-Featured-Image-6.9-1024x535-1.png 1024w, https://fr.wordpress.org/files/2025/12/Release-Edition-Featured-Image-6.9-1024x535-1-300x157.png 300w, https://fr.wordpress.org/files/2025/12/Release-Edition-Featured-Image-6.9-1024x535-1-768x401.png 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Chaque version de WordPress rend hommage à un artiste ayant laissé une marque indélébile dans le monde la musique. Le nom de code de WordPress 6.9 est «&nbsp;Gene&nbsp;», en l&rsquo;honneur du jazzman américain Gene Harris.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ce pianiste autodidacte dès l&rsquo;âge de 6 ans a infusé le jazz populaire de soul de blues et de gospel, apportant une chaleur et une signature iconique. L&rsquo;approche «&nbsp;<bdo lang=\"en\" dir=\"ltr\">bluesy</bdo>&nbsp;» du jazz de Gene Harris vivait à l&rsquo;intersection de deux mondes musicaux, apportant un paysage riche de textures et un supplément d&rsquo;âme qui restera à jamais.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Bienvenue sur WordPress&nbsp;6.9</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 6.9 apporte des changements majeurs concernant le travail collaboratif sur vos contenus éditoriaux.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La nouvelle fonctionnalité «&nbsp;Notes&nbsp;» permet d&rsquo;ajouter des commentaires au niveau des blocs lors de la rédaction de publications, simplifiant ainsi la relecture et la validation du contenu.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La palette de commandes étendue offre une navigation plus rapide dans votre administration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">La nouvelle API «&nbsp;<bdo lang=\"en\" dir=\"ltr\">Abilities</bdo>&nbsp;» fournit un système de déclaration de fonctionnalités standardisé et lisible par machine, ouvrant la voie à des flux de travail automatisés et basés sur les nouvelles générations d&rsquo;outils IA.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Cette version améliore également les performances de vos sites, notamment la vitesse de chargement des pages, et ajoute de nombreux nouveaux blocs éditoriaux, ainsi qu&rsquo;une interface de glisser-déposer plus intuitive, pour vous aider à concevoir du contenu riche et dynamique plus efficacement.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://fr.wordpress.org/download/\">Télécharger WordPress 6.9 «&nbsp;Gene&nbsp;»</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Les Notes, un nouveau système collaboratif</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Faites vos retours directement là où vous travaillez.</strong><br>Avec les notes liées directement aux blocs, votre équipe peut rester en phase, suivre les modifications, et transformer les retours en actions, tout au même endroit. Que vous travailliez sur l’écriture des textes ou sur l’affinage de la mise en page, la collaboration se fait avec fluidité directement dans le canevas de l’éditeur.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2025/12/6-9-notes.png\" alt=\"\" class=\"wp-image-19410\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Une palette de commandes disponible partout</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Vos outils sont toujours à portée de main.</strong><br>Accédez à la Palette de commandes depuis n’importe quelle partie de votre site, que vous soyez en train de rédiger votre dernier article, de travailler en profondeur sur le design du site dans l’Éditeur de site, ou de parcourir vos extensions. Tout ce dont vous avez besoin est maintenant à portée de clic.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2025/12/6-9-command-palette-everywhere.png\" alt=\"\" class=\"wp-image-19412\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Adapter le texte à son conteneur</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Un contenu qui s’adapte.</strong><br>Une nouvelle option de typographie pour les blocs de texte, à commencer par les blocs Paragraphe et Titre, qui ajuste automatiquement la taille de la police pour remplir parfaitement son conteneur. Idéal pour les bannières, les encadrés ou les éléments qui doivent se démarquer dans votre design. Aucun réglage manuel n’est nécessaire, vous obtenez instantanément un rendu propre.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2025/12/6-9-fit-text.png\" alt=\"\" class=\"wp-image-19413\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Une nouvelle API «&nbsp;Abilities&nbsp;»</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Un gestionnaire de fonctionnalités au cœur de WordPress</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 6.9 pose les bases de l&rsquo;automatisation de demain grâce à l&rsquo;API «&nbsp;Abilities&nbsp;» unifiée. En créant un registre standardisé des fonctionnalités des sites, les développeurs peuvent désormais enregistrer, valider et exécuter des actions de manière cohérente dans tous les contextes (des points de terminaison PHP et REST aux agents IA), ouvrant ainsi la voie à des expériences WordPress plus intelligentes et connectées.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Amélioration de l’accessibilité</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Plus de 30 corrections et améliorations en matière d’accessibilité, centrées sur les principales zones de l’expérience d’administration de WordPress. Cela va de la suppression complète du contenu généré par le CSS pour les technologies d’assistance, à l’amélioration des annonces des lecteurs d’écran, en passant par la correction de la position du curseur et le maintien du focus de saisie lors du clic sur les éléments de suggestion automatique.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Amélioration des performances</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 6.9 comprend un vaste ensemble d’améliorations de performances. De meilleurs résultats sur la métrique&nbsp;LCP&nbsp;(<bdo lang=\"en\" dir=\"ltr\">Largest Contentful Paint</bdo>) sont obtenus grâce à un chargement amélioré des feuilles de style conditionnelles et en ligne, et grâce au chargement des scripts avec prise en charge de l’attribut <code>fetchpriority</code> et à des optimisations du cœur complémentaires. Les avancées de l’éditeur comprennent des correctifs pour les modifications de mise en page causés par le bloc Vidéo et un chargement plus rapide du sélecteur de termes.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Et bien plus encore</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Pour une liste complète des nouvelles fonctionnalités, lisez <a href=\"https://fr.wordpress.org/2025/11/26/guide-des-changements-techniques-de-wordpress-6-9/\" data-type=\"post\" data-id=\"3383\">notre guide technique à destination des développeurs et des développeuses (en français)</a>, ou consultez le <a href=\"https://wordpress.org/download/releases/6-9\">site dédié à WordPress 6.9 (en anglais)</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">L’équipe de direction de WordPress&nbsp;6.9</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Voici l’équipe qui a coordonné le développement et la sortie de cette nouvelle version de WordPress&nbsp;:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Direction générale :&nbsp;<a href=\"https://profiles.wordpress.org/matt/\">Matt Mullenweg</a></li>\n\n\n\n<li>Coordination de la version :&nbsp;<a href=\"https://profiles.wordpress.org/akshayar/\">Akshaya Rane</a>, <a href=\"https://profiles.wordpress.org/amykamala/\">Amy Kamala</a></li>\n\n\n\n<li>Direction technique :&nbsp;<a href=\"https://profiles.wordpress.org/davidbaumwald/\">David Baumwald</a>, <a href=\"https://profiles.wordpress.org/ellatrix/\">Ella van Durpe</a>, <a href=\"https://profiles.wordpress.org/priethor/\">Héctor Prieto</a></li>\n\n\n\n<li>Direction artistique :&nbsp;<a href=\"https://profiles.wordpress.org/karmatosed/\"></a><a href=\"https://profiles.wordpress.org/fcoveram/\">Francisco Vera</a></li>\n\n\n\n<li>Gestion de projet :&nbsp;<a href=\"https://profiles.wordpress.org/audrasjb/\"></a><a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/welcher/\">Ryan Welcher</a></li>\n\n\n\n<li>Direction des tests :&nbsp;<a href=\"https://profiles.wordpress.org/krupajnanda/\"></a><a href=\"https://profiles.wordpress.org/psykro/\">Jonathan Bossenger</a>, <a href=\"https://profiles.wordpress.org/krupajnanda/\">Krupa Nanda</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Merci aux contributeurs et contributrices</h2>\n\n\n\n<p class=\"wp-block-paragraph\">La mission de WordPress est de <a href=\"https://fr.wordpress.org/about/\">démocratiser la publication de contenu</a> et ce projet <a href=\"https://opensource.org/osd-annotated\">embrasse les libertés fondamentales de l&rsquo;open-source (en anglais)</a>. Une communauté mondiale et diversifiée supporte cet effort.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 6.9 n’aurait pas pu sortir sans la contribution passionnée de plus de&nbsp;<strong>900 personnes provenant de près de 67 pays différents</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ce travail collaboratif a abouti à plus de 340 améliorations et correctifs, ce qui donne une nouvelle version majeure stable et efficace – un vrai témoignage de la vivacité de l&rsquo;écosystème open-source de notre CMS.</p>\n\n\n\n<div class=\"wp-block-group alignwide is-layout-constrained wp-block-group-is-layout-constrained\">\n<p class=\"has-extra-small-font-size wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/o-o/\">2046</a> · <a href=\"https://profiles.wordpress.org/aakashverma1/\">Aakash Verma</a> · <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> · <a href=\"https://profiles.wordpress.org/aaronrobertshaw/\">Aaron Robertshaw</a> · <a href=\"https://profiles.wordpress.org/aarti1318/\">Aarti Chauhan</a> · <a href=\"https://profiles.wordpress.org/thehercules/\">Aashish Sharma</a> · <a href=\"https://profiles.wordpress.org/aatospaja/\">aatospaja</a> · <a href=\"https://profiles.wordpress.org/abduremon/\">Abdur Rahman Emon</a> · <a href=\"https://profiles.wordpress.org/hurayraiit/\">Abu Hurayra</a> · <a href=\"https://profiles.wordpress.org/kawauso/\">Adam Harley (Kawauso)</a> · <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> · <a href=\"https://profiles.wordpress.org/zieladam/\">Adam Zieliński</a> · <a href=\"https://profiles.wordpress.org/adityab98/\">Aditya Bansode</a> · <a href=\"https://profiles.wordpress.org/b1ink0/\">Aditya Dhade</a> · <a href=\"https://profiles.wordpress.org/adityashah2411/\">aditya shah</a> · <a href=\"https://profiles.wordpress.org/iamadisingh/\">Aditya Singh</a> · <a href=\"https://profiles.wordpress.org/aduth/\">aduth</a> · <a href=\"https://profiles.wordpress.org/agulbra/\">agulbra</a> · <a href=\"https://profiles.wordpress.org/elazzabi/\">Ahmed</a> · <a href=\"https://profiles.wordpress.org/ajaxstardust/\">ajaxStardust</a> · <a href=\"https://profiles.wordpress.org/ajitbohra/\">Ajit Bohra</a> · <a href=\"https://profiles.wordpress.org/akanshusingh/\">Akanshu Singh</a> · <a href=\"https://prof