\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:9:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://jasonrouet.com/pique-nique-pre-wordcamp-europe-2026-a-cracovie/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"Pique-nique pré-WordCamp Europe 2026 à Cracovie\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:2:{s:4:\"href\";s:71:\"https://jasonrouet.com/pique-nique-pre-wordcamp-europe-2026-a-cracovie/\";s:3:\"rel\";s:9:\"alternate\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"updated\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2026-03-27T11:05:17.000+00:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"published\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2026-03-27T11:05:17.000+00:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"summary\";a:1:{i:0;a:5:{s:4:\"data\";s:539:\"Comme chaque année avant le WordCamp Europe, Patricia Brun Torre organise le plus bucolique des événements informels de notre communauté  : le traditionnel pique-nique la veille du début de l’événement. Cette année, ce sera sur les rives de la Vistule, à Cracovie. Cette année, je suis heureux de pouvoir être présent et de le co-organiser avec […]\nL’article Pique-nique pré-WordCamp Europe 2026 à Cracovie est apparu en premier sur Jason Rouet | WordPress, Open Web, Open Source, contributions & geekeries diverses..\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"content\";a:1:{i:0;a:5:{s:4:\"data\";s:4357:\"\n        \n<p class=\"wp-block-paragraph\">Comme chaque année avant le WordCamp Europe, Patricia Brun Torre organise le plus bucolique des événements informels de notre communauté&#160;&#160;: le traditionnel pique-nique la veille du début de l&rsquo;événement. Cette année, ce sera sur les rives de la Vistule, à Cracovie.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Cette année, je suis heureux de pouvoir être présent et de le co-organiser avec Patricia et Michelle Bulloch&#160;&#160;!</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Depuis la reprise du WordCamp Europe en personne suite après la pandémie, nous en sommes à la 6e édition&#160;&#160;: la <a href=\"https://patriciabt.com/blog/wceu-2022-picnic-pre-event/\">première édition à Porto en 2022</a>, puis j&rsquo;avais co-organisé <a href=\"https://patriciabt.com/blog/wceu-2023-picnic-pre-event/\">Athènes en 2023</a>, <a href=\"https://patriciabt.com/blog/wceu-2024-picnic-pre-event/\">Turin en 2024</a>, puis <a href=\"https://patriciabt.com/event/wceu-2025-picnic-pre-event/\">Bâle en 2025</a> (où je n&rsquo;étais pas présent). C&rsquo;est devenu un rendez-vous à part à chaque WCEU. Le principe n&rsquo;a pas changé&#160;&#160;: un pique-nique informel dans un parc public, la veille de l&rsquo;ouverture de l&rsquo;événement, afin de se retrouver dans un cadre sympathique.</p>\n\n\n\n<div class=\"wp-block-group has-background-color has-primary-background-color has-text-color has-background has-link-color wp-elements-49a74e4021a5c5867c6133dfaa2841a3 is-layout-constrained wp-container-core-group-is-layout-98b0cc04 wp-block-group-is-layout-constrained\" style=\"border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px;padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">\n<p class=\"wp-block-paragraph\"><strong>Les infos pratiques&#160;&#160;:</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4c5.png\" alt=\"📅\" class=\"wp-smiley\" style=\"height: 1em;max-height: 1em\" //> Mercredi 3 juin 2026</li>\n\n\n\n<li><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f550.png\" alt=\"🕐\" class=\"wp-smiley\" style=\"height: 1em;max-height: 1em\" //> À partir de 13h00 (jusqu&rsquo;à 16h00 environ)</li>\n\n\n\n<li><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f4cd.png\" alt=\"📍\" class=\"wp-smiley\" style=\"height: 1em;max-height: 1em\" //> Près du Przystań Wawel Resto Bar, sur les berges de la Vistule</li>\n</ul>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">Il n&rsquo;y a pas de formulaire d&rsquo;inscription cette année, l&rsquo;événement est ouvert à tout le monde. Que vous veniez pour la première fois à un WCEU, que vous soyez un habitué, en famille, introverti ou non&#8230; nous accueillerons tout le monde comme il se doit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Amenez de quoi manger, à partager ou non, votre sourire et votre curiosité.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Cet événement est organisé de manière indépendante et n&rsquo;est pas lié à l&rsquo;organisation officielle de WCEU. Néanmoins, il devrait être référencé prochainement sur la page des side-events du site officiel et les <a href=\"https://europe.wordcamp.org/2026/community/code-of-conduct/\">règles de la communauté</a> s&rsquo;y appliquent évidemment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Si tu viens au WordCamp Europe 2026 et que tu veux commencer la semaine dans la bonne humeur, on se donne rendez-vous le 3 juin sur les berges de la Vistule&#160;&#160;!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><img src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f449.png\" alt=\"👉\" class=\"wp-smiley\" style=\"height: 1em;max-height: 1em\" //> <a href=\"https://patriciabt.com/event/wceu-2026-picnic-pre-event/\">Patricia a publié un excellent article (en anglais) sur son site avec un lien pour ajouter l&rsquo;événement à votre calendrier en quelques clics.</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n<p>L’article <a href=\"https://jasonrouet.com/pique-nique-pre-wordcamp-europe-2026-a-cracovie/\">Pique-nique pré-WordCamp Europe 2026 à Cracovie</a> est apparu en premier sur <a href=\"https://jasonrouet.com\">Jason Rouet | WordPress, Open Web, Open Source, contributions &amp; geekeries diverses.</a>.</p>\n\n    \";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"author\";a:1:{i:0;a:6:{s:4:\"data\";s:46:\"\n            \n                                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"name\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Jason ROUET\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:6:\"source\";a:1:{i:0;a:6:{s:4:\"data\";s:67:\"\n                    \n                            \n                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:2:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://jasonrouet.com/categorie/wordpress/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Jason Rouet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}i:8;a:6:{s:4:\"data\";s:70:\"\n    \n    \n    \n    \n    \n    \n    \n            \n                \n    \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:9:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"https://holdmywp.com/honeypot-contact-form-7/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:77:\"Comment configurer un pot de miel sur Contact Form 7 (La Sentinelle antispam)\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:2:{s:4:\"href\";s:45:\"https://holdmywp.com/honeypot-contact-form-7/\";s:3:\"rel\";s:9:\"alternate\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"updated\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2026-02-17T17:38:20.000+00:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"published\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2026-02-17T17:38:20.000+00:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"summary\";a:1:{i:0;a:5:{s:4:\"data\";s:122:\"Guide de configuration rapide de l\'extension \"La Sentinelle antispam\" et intégration d\'un pot de miel sur Contact Form 7.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"content\";a:1:{i:0;a:5:{s:4:\"data\";s:10536:\"\n        \n<p><strong><a href=\"https://fr.wordpress.org/plugins/la-sentinelle-antispam/\" target=\"_blank\" rel=\"noopener nofollow\" title=\"La Sentinelle antispam\">La Sentinelle antispam</a></strong> est une petite extension très pratique pour <strong>sécuriser les formulaires</strong> de son site et <strong>limiter les spams</strong>. Elle <strong>protège les formulaires natifs</strong> de WordPress : commentaires, connexion, inscription et mot de passe oublié. La Sentinelle intègre également les formulaires ajoutés par de nombreuses extensions comme <strong>Contact Form 7</strong>, Forminator, WooCommerce ou encore Easy Digital Downloads.</p>\n\n\n\n<p><strong>Guide rapide et concis</strong> pour configurer les réglages généraux de votre Sentinelle et protéger les formulaires <strong>Contact Form 7</strong> avec un Pot de miel (<strong>Honeypot</strong>).</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img width=\"559\" height=\"300\" src=\"https://holdmywp.com/wp-content/uploads/2026/02/la-sentinelle-antispam-min.webp\" alt=\"Capture d\'écran de l\'extension « La sentinelle antispam » dans le répertoire WordPress.org\" class=\"wp-image-7898\" //><figcaption class=\"wp-element-caption\"><em>Capture d&rsquo;écran de l&rsquo;extension « La Sentinelle antispam » dans le répertoire WordPress.org</em></figcaption></figure>\n\n\n<h2 class=\"wp-block-heading\" id=\"reglages-generaux\">Réglages généraux</h2>\n\n<h3 class=\"wp-block-heading\" id=\"page-des-reglages\">Page des réglages</h3>\n\n\n<p>Retrouvez la page de réglages de l&rsquo;extension <strong>La Sentinelle antispam</strong> dans l&rsquo;interface d&rsquo;administration de votre site : <strong>Réglages &gt; La Sentinelle</strong>.</p>\n\n\n\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6994ca0b7cd3d&quot;}\" data-wp-interactive=\"core/image\" data-wp-key=\"6994ca0b7cd3d\" class=\"wp-block-image size-large wp-lightbox-container\"><img width=\"1024\" height=\"402\" data-wp-class--hide=\"state.isContentHidden\" data-wp-class--show=\"state.isContentVisible\" data-wp-init=\"callbacks.setButtonStyles\" data-wp-on--click=\"actions.showLightbox\" data-wp-on--load=\"callbacks.setButtonStyles\" data-wp-on-window--resize=\"callbacks.setButtonStyles\" src=\"https://holdmywp.com/wp-content/uploads/2026/02/la-sentinelle-antispam-reglages-min-1024x402.webp\" alt=\"Capture d\'écran de la page des réglages de l\'extension &quot;La Sentinelle antispam&quot;\" class=\"wp-image-7900\" //><button class=\"lightbox-trigger\" type=\"button\" aria-haspopup=\"dialog\" aria-label=\"Agrandir\" data-wp-init=\"callbacks.initTriggerButton\" data-wp-on--click=\"actions.showLightbox\" data-wp-style--right=\"state.imageButtonRight\" data-wp-style--top=\"state.imageButtonTop\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\"><em>Capture d&rsquo;écran de la page des réglages de l&rsquo;extension « La Sentinelle antispam »</em></figcaption></figure>\n\n\n<h3 class=\"wp-block-heading\" id=\"configuration-rapide\">Configuration rapide</h3>\n\n\n<p>La configuration suivante est simple : elle limitera considérablement les spams sur la majorité des sites tout en permettant à l&rsquo;administrateur de contrôler d’éventuels faux-positifs en enregistrant temporairement les spams.</p>\n\n\n\n<p>Les options non citées ci-dessous ne sont pas activés.</p>\n\n\n\n<div id=\"config\" class=\"wp-block-group card card--no-tag has-bg-0-color has-fg-2-background-color has-text-color has-background has-link-color wp-elements-795c58aeaaa4d063466f6b540bb1f158 has-global-padding is-layout-constrained wp-block-group-is-layout-constrained\"><h4 class=\"wp-block-heading no-decoration has-bg-0-color has-text-color has-link-color wp-elements-f9121a382fdfa32b4ad1440158c8a917\" id=\"filtre-contre-les-indesirables\">Filtre contre les indésirables</h4>\n\n\n<p>✅ Utiliser le pot de miel.</p>\n\n\n\n<p>✅ Mettre en place un délai d’attente pour envoyer le formulaire.</p>\n\n\n<h4 class=\"wp-block-heading no-decoration has-bg-0-color has-text-color has-link-color wp-elements-a61d25b3e2524430b695347b2792b15d\" id=\"formulaires\">Formulaires</h4>\n\n\n<p>✅ Activer les filtres d’indésirables pour les formulaires de commentaire WordPress.</p>\n\n\n\n<p>✅ Activer les filtres d’indésirables pour le formulaire de connexion de WordPress.</p>\n\n\n\n<p>✅ Activer les filtres d’indésirables pour le formulaire de réinitialisation de mot de passe de WordPress.</p>\n\n\n\n<p>✅ Activer les filtres d’indésirables pour le formulaire d’enregistrement de WordPress.</p>\n\n\n<h4 class=\"wp-block-heading no-decoration has-bg-0-color has-text-color has-link-color wp-elements-41c29a2c813483eff1c7cd60581af1af\" id=\"divers\">Divers</h4>\n\n\n<p>✅ Enregistrer les soumissions indésirables.</p>\n\n\n\n<p>✅ Supprimer les anciennes soumissions indésirables.</p>\n</div>\n\n\n<h2 class=\"wp-block-heading\" id=\"proteger-ses-formulaires-cf7\">Protéger ses formulaires CF7</h2>\n\n\n<p>Pour protéger un formulaire, rendez-vous sur la page dédiée dans l&rsquo;interface d&rsquo;administration de votre site : <strong>Contact &gt; Formulaires de contact</strong> puis éditez le formulaire à protéger.</p>\n\n\n\n<p>Une fois sur l&rsquo;interface d&rsquo;édition de votre formulaire, ajoutez simplement un champ « La Sentinelle » en cliquant sur le bouton dédié (voir capture d&rsquo;écran) situé au-dessus de la zone de texte.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img width=\"141\" height=\"26\" src=\"https://holdmywp.com/wp-content/uploads/2026/02/la-sentinelle-antispam-cf7-button-min.webp\" alt=\"Capture d\'écran d\'un bouton d\'ajout d\'un champ &quot;pot de miel&quot; à un formulaire CF7 avec La Sentinelle antispam.\" class=\"wp-image-7892\" //><figcaption class=\"wp-element-caption\"><em>Capture d&rsquo;écran d&rsquo;un bouton d&rsquo;ajout d&rsquo;un champ « pot de miel » à un formulaire CF7 avec La Sentinelle antispam.</em></figcaption></figure>\n\n\n\n<p>Une fenêtre de configuration s&rsquo;ouvre, laissez les champs par défaut et cliquez sur « Insérer la balise ».</p>\n\n\n\n<figure data-wp-context=\"{&quot;imageId&quot;:&quot;6994ca0b7d42a&quot;}\" data-wp-interactive=\"core/image\" data-wp-key=\"6994ca0b7d42a\" class=\"wp-block-image size-full wp-lightbox-container\"><img loading=\"lazy\" width=\"744\" height=\"743\" data-wp-class--hide=\"state.isContentHidden\" data-wp-class--show=\"state.isContentVisible\" data-wp-init=\"callbacks.setButtonStyles\" data-wp-on--click=\"actions.showLightbox\" data-wp-on--load=\"callbacks.setButtonStyles\" data-wp-on-window--resize=\"callbacks.setButtonStyles\" src=\"https://holdmywp.com/wp-content/uploads/2026/02/la-sentinelle-antispam-cf7-shortcode-settings-min.webp\" alt=\"Capture d\'écran de la modale des réglages d\'un shortcode &quot;la sentinelle antispam&quot; à contact form 7\" class=\"wp-image-7894\" //><button class=\"lightbox-trigger\" type=\"button\" aria-haspopup=\"dialog\" aria-label=\"Agrandir\" data-wp-init=\"callbacks.initTriggerButton\" data-wp-on--click=\"actions.showLightbox\" data-wp-style--right=\"state.imageButtonRight\" data-wp-style--top=\"state.imageButtonTop\">\n			\n				\n			\n		</button><figcaption class=\"wp-element-caption\"><em>Capture d&rsquo;écran de la modale des réglages d&rsquo;un shortcode « la sentinelle antispam » à contact form 7</em></figcaption></figure>\n\n\n\n<p>Faites attention à bien <strong>insérer la balise La Sentinelle AVANT la balise d&rsquo;envoi du formulaire</strong> comme celle ci-dessous 👇️</p>\n\n\n<pre class=\"wp-block-code\"><span><code class=\"hljs language-php\"><span class=\"hljs-comment\"># Balise pour le bouton de soumission Contact Form 7</span>\n&#091;submit <span class=\"hljs-string\">\"Envoyer\"</span>]</code></span></pre>\n\n\n<p>Pour la lisibilité, j&rsquo;aime bien segmenter mes champs dans des labels, ce qui donne pour le Honeypot :</p>\n\n\n<pre class=\"wp-block-code\"><span><code class=\"hljs language-php\"><span class=\"hljs-comment\"># Balise \"Pot de miel\"</span>\n&lt;label&gt;&#091;la_sentinelle la_sentinelle<span class=\"hljs-number\">-713</span>]&lt;/label&gt;</code></span></pre>\n\n<h2 class=\"wp-block-heading\" id=\"la-sentinelle-antispam-une-extension-antiindesirables-facile-a-mettre-en-place\">La Sentinelle antispam, une extension anti-indésirables facile à mettre en place</h2>\n\n\n<p>On a vu comment configurer très rapidement des protections performantes pour vos formulaires WordPress, tout en étant transparent pour l&rsquo;internaute qui n&rsquo;est pas gêné par des CAPTCHA et autres vérifications. De plus, tout est traité localement sur votre site, ce qui assure un meilleur contrôle des données de vos utilisateurs.</p>\n\n\n\n<p>Si vous voulez en savoir plus sur La Sentinelle antispam, je vous invite à <a href=\"https://fr.wordpress.org/plugins/la-sentinelle-antispam/\" target=\"_blank\" rel=\"noopener nofollow\" title=\"visiter la page officielle de l\'extension\">visiter la page officielle de l&rsquo;extension</a> sur le dépôt WordPress.</p>\n\n\n\n<p>J’espère que cette publication vous aidera. Si vous avez des questions, besoin d&rsquo;aide avec votre site, ou que vous voulez apporter votre contribution, n’hésitez pas à me <a href=\"https://holdmywp.com/contact/\">contacter</a> ou à laisser un petit commentaire !</p>\n\n\n\n<section id=\"sources\" class=\"wp-block-group has-global-padding is-layout-constrained wp-block-group-is-layout-constrained\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40)\">\n<div class=\"wp-block-group card card--no-tag has-global-padding is-layout-constrained wp-container-core-group-is-layout-24567ffd wp-block-group-is-layout-constrained\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><h2 class=\"wp-block-heading no-decoration\" id=\"sources-amp-references\">Sources &amp; références</h2>\n\n\n<div class=\"wp-block-group has-global-padding is-layout-constrained wp-container-core-group-is-layout-c748ba87 wp-block-group-is-layout-constrained\" style=\"padding-left:var(--wp--preset--spacing--40)\">\n<ul class=\"wp-block-list\">\n<li><a href=\"https://fr.wordpress.org/plugins/la-sentinelle-antispam/\" target=\"_blank\" rel=\"noopener nofollow\" title=\"La Sentinelle antispam\">La Sentinelle antispam</a></li>\n\n\n\n<li><a href=\"https://timelord.nl/?lang=en\" target=\"_blank\" rel=\"noopener nofollow\" title=\"Site du développeur de l\'extension (en anglais)\">Site du développeur de l&rsquo;extension (en anglais)</a></li>\n</ul>\n</div>\n</div>\n</section>\n\n<p><a href=\"https://holdmywp.com/honeypot-contact-form-7/\">Source</a></p>\n    \";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"author\";a:1:{i:0;a:6:{s:4:\"data\";s:46:\"\n            \n                                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"name\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Quentin Le Duff\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:6:\"source\";a:1:{i:0;a:6:{s:4:\"data\";s:67:\"\n                    \n                            \n                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:2:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://holdmywp.com/tag/wordpress/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"HoldMyWP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}i:9;a:6:{s:4:\"data\";s:70:\"\n    \n    \n    \n    \n    \n    \n    \n            \n                \n    \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:9:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://yesweblog.fr/comment-activer-le-module-imagick-chez-nuxit/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"Comment activer le module imagick chez Nuxit\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:2:{s:4:\"href\";s:66:\"https://yesweblog.fr/comment-activer-le-module-imagick-chez-nuxit/\";s:3:\"rel\";s:9:\"alternate\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"updated\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2026-01-28T17:47:59.000+00:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"published\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"2026-01-28T17:47:59.000+00:00\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"summary\";a:1:{i:0;a:5:{s:4:\"data\";s:484:\"Nouvel Article\nVu que je suis webmaster WordPress, je suis régulièrement interrogée et sollicitée sur les recommandations de l’outil de santé natif de WordPress. Et une recommandation revient très souvent parmi les questions que je reçois, à savoir : En l’occurrence, même si cette recommandation n’est pas une injonction, elle est a priori interprétée comme importante voire […]\n- Yes We Blog ! - Webmaster WordPress - Griselidis Gaillet - Conceptrice de sites web\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"content\";a:1:{i:0;a:5:{s:4:\"data\";s:571:\"\n        <p>Nouvel Article</p>\n<p>Vu que je suis webmaster WordPress, je suis régulièrement interrogée et sollicitée sur les recommandations de l&#8217;outil de santé natif de WordPress. Et une recommandation revient très souvent parmi les questions que je reçois, à savoir : En l&#8217;occurrence, même si cette recommandation n&#8217;est pas une injonction, elle est a priori interprétée comme importante voire [&#8230;]</p>\n<p>- <a href=\"https://yesweblog.fr\">Yes We Blog ! - Webmaster WordPress - Griselidis Gaillet - Conceptrice de sites web</a></p>\n\n    \";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:4:\"type\";s:4:\"html\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"author\";a:1:{i:0;a:6:{s:4:\"data\";s:46:\"\n            \n                                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"name\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Griselidis Gaillet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:6:\"source\";a:1:{i:0;a:6:{s:4:\"data\";s:67:\"\n                    \n                            \n                \";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:27:\"http://www.w3.org/2005/Atom\";a:2:{s:2:\"id\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"https://yesweblog.fr/category/wordpress/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Yes we blog\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:512;s:7:\"headers\";a:11:{s:4:\"date\";s:29:\"Wed, 13 May 2026 06:14:50 GMT\";s:12:\"content-type\";s:20:\"application/atom+xml\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:4:\"link\";s:64:\"<https://fluxplanet.wpfr.net/wp-json/>; rel=\"https://api.w.org/\"\";s:13:\"cache-control\";s:35:\"no-cache, no-store, must-revalidate\";s:6:\"pragma\";s:8:\"no-cache\";s:7:\"expires\";s:1:\"0\";s:13:\"last-modified\";s:29:\"Fri, 27 Mar 2026 09:11:08 GMT\";s:4:\"etag\";s:36:\"W/\"8a238894674d1e362b09c012ca6cb926\"\";s:6:\"server\";s:22:\"o2switch-PowerBoost-v3\";s:16:\"content-encoding\";s:2:\"br\";}s:5:\"build