(13,1,'2026-05-04 14:28:55','2026-05-04 12:28:55','<!-- wp:group {\"metadata\":{\"categories\":[\"twentytwentyfive_page\",\"banner\",\"featured\"],\"patternName\":\"twentytwentyfive/page-link-in-bio-wide-margins\",\"name\":\"Lien dans la bio avec profil, liens et des marges externes larges\"},\"align\":\"full\",\"className\":\"is-style-section-1\",\"style\":{\"dimensions\":{\"minHeight\":\"100vh\"},\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\",\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull is-style-section-1\" style=\"min-height:100vh;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--80);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80);padding-left:var(--wp--preset--spacing--80)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"150px\",\"bottomRight\":\"150px\"}}}} -->\n<figure class=\"wp-block-image aligncenter size-full has-custom-border\"><img src=\"http://localhost/wp-content/themes/twentytwentyfive/assets/images/woman-splashing-water.webp\" alt=\"Femme sur la plage, éclaboussant l’eau.\" style=\"border-top-left-radius:150px;border-bottom-right-radius:150px;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"left\"} -->\n<h2 class=\"wp-block-heading has-text-align-left\">Nora Winslow Keene</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Je suis Baya, une avocate de droit public basée sur Chambéry. Je suis diplômée de l’Université Grenoble-Alpes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:social-links {\"iconColor\":\"currentColor\",\"iconColorValue\":\"currentColor\",\"className\":\"is-style-logos-only\"} -->\n<ul class=\"wp-block-social-links has-icon-color is-style-logos-only\"><!-- wp:social-link {\"url\":\"#\",\"service\":\"x\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"instagram\"} /-->\n\n<!-- wp:social-link {\"url\":\"#\",\"service\":\"whatsapp\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:code -->\n<pre class=\"wp-block-code\"><code></code></pre>\n<!-- /wp:code -->','','','trash','closed','closed','','__trashed-2','','','2026-05-04 14:28:55','2026-05-04 12:28:55','',0,'http://localhost/?page_id=13',0,'page','',0),
